+#[test]
+fn noise_only_step_presence_is_characterized_without_a_speech_posterior_claim() {
+    let (mut source, recorded_clean) = input();
+    for (frame, clean) in recorded_clean.iter().enumerate() {
+        // Preserve the exact added-noise realization and independent channel.
+        source[frame * 2] -= *clean as f32;
+    }
+    let clean = vec![0.0_f64; recorded_clean.len()];
+    let times = [0.0_f64, 0.1, 0.2, 0.26, 0.3, 0.375, 0.45, 0.6, 0.9];
+    let mut records = 0;
+    let mut checked_records = 0;
+    let mut maximum_power_error = 0.0_f64;
+    for low_latency in [false, true] {
+        let mut plugin = DenoiserPlugin::from_params(
+            2,
+            DenoiserPluginParams {
+                low_latency,
+                spatial_denoise: false,
+                polyphonic_detection: false,
+                psychoacoustic_masking: false,
+                ..Default::default()
+            },
+        );
+        plugin.initialize(48_000.0).unwrap();
+        let size = plugin.config.fft_size;
+        let hop = plugin.config.hop_size;
+        let first = (100.0 * size as f64 / 48_000.0).ceil() as usize;
+        let last = (4000.0 * size as f64 / 48_000.0).floor() as usize;
+        let mut rendered = Vec::with_capacity(source.len());
+        let mut end = 0;
+        let mut next_time = 0;
+        for input in source.chunks(hop * 2) {
+            let mut block = input.to_vec();
+            let frames = block.len() / 2;
+            plugin
+                .process_in_place(&mut block, &ProcessContext::new(48_000, frames))
+                .unwrap();
+            rendered.extend_from_slice(&block);
+            end += frames;
+            let center = end.saturating_sub(hop) as f64 / 48_000.0;
+            if frames != hop || next_time >= times.len() || center < times[next_time] {
+                continue;
+            }
+            let active = plugin.mcra.frame_counter[0] >= plugin.mcra.bootstrap_frames;
+            let input_power = |channel: usize, bin: usize| {
+                if active {
+                    plugin.decision_directed.prev_power[channel][bin]
+                } else {
+                    plugin.get_power_at_bin(channel, bin)
+                }
+            };
+            let requested = times[next_time];
+            next_time += 1;
+            for channel in 0..2 {
+                let power: f64 = (first..=last)
+                    .map(|bin| f64::from(input_power(channel, bin)))
+                    .sum();
+                let weighted_p: f64 = (first..=last)
+                    .map(|bin| {
+                        f64::from(input_power(channel, bin))
+                            * f64::from(plugin.mcra.speech_presence[channel][bin])
+                    })
+                    .sum();
+                let above_half = (first..=last)
+                    .filter(|&bin| plugin.mcra.speech_presence[channel][bin] > 0.5)
+                    .count();
+                println!(
+                    "NOISE_PRESENCE {}",
+                    serde_json::json!({"low_latency":low_latency,"channel":channel,"condition":if channel==0 {"noise_only_40db_step"} else {"independent_gentle_noise"},"requested_source_time":requested,"source_window_center":center,"power_weighted_p":weighted_p/power.max(1e-30),"bins_above_half":above_half,"bins":last-first+1})
+                );
+            }
+            let mut bins: Vec<_> = (first..=last)
+                .map(|bin| (bin, powers(&clean, &source, end, size, bin).2))
+                .collect();
+            // Noise-only source ground truth chooses bins, never production p.
+            bins.sort_by(|a, b| b.1.total_cmp(&a.1));
+            for (bin, total) in bins.into_iter().take(8) {
+                let observed = f64::from(input_power(0, bin));
+                let error = (observed - total).abs() / (1.0 + total);
+                if active {
+                    maximum_power_error = maximum_power_error.max(error);
+                    assert!(error < 2e-6, "independent noise-power mismatch {error}");
+                    checked_records += 1;
+                }
+                println!(
+                    "NOISE_COMPONENT {}",
+                    serde_json::json!({"low_latency":low_latency,"requested_source_time":requested,"source_window_center":center,"bin":bin,"true_noise_periodogram":total,"observed_power":if active {Some(observed)} else {None},"gain_frame_active":active,"estimated_noise":plugin.mcra.noise_psd[0][bin],"speech_probability":plugin.mcra.speech_presence[0][bin],"final_gain":plugin.gains.smoothed_gain[0][bin]})
+                );
+                records += 1;
+            }
+        }
+        assert_eq!(next_time, times.len());
+        let latency = plugin.latency_samples();
+        for channel in 0..2 {
+            for (start, end) in [(14_400, 21_600), (28_800, 33_600), (40_800, 45_600)] {
+                let before: f64 = (start..end)
+                    .map(|frame| f64::from(source[frame * 2 + channel]).powi(2))
+                    .sum();
+                let after: f64 = (start..end)
+                    .map(|frame| f64::from(rendered[(frame + latency) * 2 + channel]).powi(2))
+                    .sum();
+                println!(
+                    "NOISE_RENDER {}",
+                    serde_json::json!({"low_latency":low_latency,"channel":channel,"start_frame":start,"end_frame":end,"latency_frames":latency,"gain_db":10.0*(after/before).log10()})
+                );
+            }
+        }
+    }
+    assert_eq!(records, 144);
+    println!(
+        "noise_presence_trace_summary records={records} checked_records={checked_records} maximum_scaled_power_error={maximum_power_error:e}"
+    );
+}
